// CSD_RATIONALE_BEGIN
// Targeted improvements over the best attempt (40.8% accuracy, 91.8% syntax).
//
// Diagnosis:
//   (a) Attempts 66 and 68 that used RenderedEndsWith scored 0.0% and 10.2%.
//       The Qwen tokenizer emits "<<" as a single token; `next == "<<"` is
//       empirically correct and is kept here.
//   (b) The budget-pressure force-open (`maxSteps - steps <= 4`) fires AFTER the
//       model has already produced a correct final span, corrupting the last visible
//       span with garbage and zero-ing the extracted answer.  Fix: track `seenSpan`
//       and only force-open when NO span has been seen yet.
//   (c) `parser.IsCompletePrefix(["n"])` is true for a single identifier.  Eager
//       close on any complete prefix produces `<<n>>` spans (median length 1.00)
//       that extract as wrong answers.  Fix: require |currentConstrainedOut| >= 3
//       before eager close.  When the span is complete but short, keep generating;
//       the model will append operators/operands to reach a real formula before we
//       close at budget pressure via CloseSpanWithinBudget.
//   (d) The example in prior guidance used "<<3+4=7>>" which contains `=`, likely
//       invalid in the arithmetic expression grammar.  New guidance avoids `=`.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span / force-open branch: OpenConstrainedSpan sets currentConstrainedOut := [];
//   parser.IsValidPrefix([]) holds by method precondition; insideConstrainedOut := true. ✓
//
//   Outside-span / UnconstrainedStep branch: insideConstrainedOut stays false (implication
//   vacuously true) until next == "<<". Then EnterObservedConstrainedSpan sets
//   currentConstrainedOut := []; parser.IsValidPrefix([]) holds by precondition. ✓
//
//   CloseSpanWithinBudget branch (budget pressure): helper postcondition directly
//   guarantees insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). ✓
//
//   CloseConstrainedSpan branch (complete, length >= 3): sets insideConstrainedOut := false
//   making implication vacuously true; sets currentConstrainedOut := []. ✓
//
//   AdaptiveConstrainedStep + AppendConstrainedToken branch (normal step, or complete
//   but length < 3): AdaptiveConstrainedStep hard-masks to parser-valid tokens plus EOS.
//   EOS causes break; generated/inside/current unchanged, invariant holds by induction.
//   Otherwise AppendConstrainedToken extends currentConstrainedOut by the valid next
//   token, preserving parser.IsValidPrefix by that token's parser validity. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: equality at steps = 0. ✓
//
//   Force-open branch: OpenConstrainedSpan appends exactly 1 token; steps += 1.
//   Growth 1 <= 1. ✓
//
//   UnconstrainedStep branch: steps += 1; EOS breaks without appending (growth 0 <=
//   1). Otherwise generated grows by 1 token; EnterObservedConstrainedSpan leaves
//   generated unchanged. Growth 1 <= 1. ✓
//
//   CloseSpanWithinBudget branch: closeBudget = maxSteps - steps; postcondition gives
//   |cg| <= |generated| + closeBudget. After steps := maxSteps:
//   |generated| <= |generatedPrefix| + (old steps) + (maxSteps - old steps)
//              = |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
//
//   CloseConstrainedSpan branch: steps += 1; helper appends at most 1 token (>>).
//   Growth 1 <= 1. ✓
//
//   AdaptiveConstrainedStep branch: steps += 1; EOS breaks without appending (growth
//   0 <= 1). Otherwise AppendConstrainedToken appends exactly 1 token. Growth 1 <= 1. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve math word problems step by step. At each calculation step and for the " +
  "final answer, write the complete arithmetic expression inside << >>. " +
  "Use the symbolic variable names from the problem (like n1, n2, price, rate) " +
  "and Python-style operators (+, -, *, /, //, int()). " +
  "Write COMPLETE multi-variable formulas, not single variable names alone. " +
  "Example: The total cost is <<n1 * price1 + n2 * price2>> dollars. " +
  "The LAST << >> expression in your response is your final answer.");

var steps: nat := 0;
var narrowThreshold: nat := 12;
var seenSpan: bool := insideConstrained;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if maxSteps - steps <= 4 && steps > 0 && !seenSpan {
      // Budget pressure AND no span seen yet: force open a constrained span so
      // the output contains at least one << >> pair.
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
      seenSpan := true;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        if next == "<<" {
          // Detect delimiter via exact token match (empirically correct for Qwen).
          generated, insideConstrainedOut, currentConstrainedOut :=
            helpers.EnterObservedConstrainedSpan(lm, generated);
          seenSpan := true;
        }
      }
    }
  } else {
    // Inside a constrained span.
    if maxSteps - steps <= 3 {
      // Near budget: use CloseSpanWithinBudget to reach a completable state
      // and close gracefully, regardless of current completeness.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= 3 {
      // Eagerly close complete spans of sufficient token length (>= 3 prevents
      // closing on single-variable placeholders like <<n>> that are complete
      // but semantically trivial).
      var cg, ci, cc := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else {
      // Normal constrained generation: hard-masked + adaptive group boosts.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

cost := steps;

